"""PDF report generator for the brain tumor classifier."""
import io
from datetime import datetime

import numpy as np
from PIL import Image
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import (
    Image as RLImage, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle,
)

from doctor_assist import CLASS_NAMES

DISCLAIMER = (
    "This report was generated by an AI research prototype and is intended as decision "
    "support only. It is not a diagnosis. All findings must be reviewed and confirmed by "
    "a qualified radiologist or physician before any clinical decision is made."
)


def _pil_to_flowable(img, width_mm):
    if isinstance(img, np.ndarray):
        img = Image.fromarray(img.astype("uint8"))
    img = img.convert("RGB")
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    w = width_mm * mm
    return RLImage(buf, width=w, height=w * img.height / img.width)


def _esc(text):
    return (str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


def generate_report_pdf(patient, image, cam_image, probs, assist, clinician_notes="", clinician_name=""):
    """Return PDF bytes.

    patient: dict (name, id, age, sex, scan_date, indication)
    image: PIL image of the uploaded scan
    cam_image: numpy RGB array of the Grad-CAM overlay
    probs: list of 4 probabilities
    assist: dict returned by doctor_assist.analyze
    """
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=18*mm, rightMargin=18*mm,
                            topMargin=16*mm, bottomMargin=16*mm,
                            title="Brain MRI AI-Assisted Report")
    ss = getSampleStyleSheet()
    h1 = ParagraphStyle("h1", parent=ss["Title"], fontSize=18, spaceAfter=2)
    h2 = ParagraphStyle("h2", parent=ss["Heading2"], fontSize=12, spaceBefore=10, spaceAfter=4,
                        textColor=colors.HexColor("#1f3b57"))
    body = ParagraphStyle("body", parent=ss["BodyText"], fontSize=9.5, leading=13)
    small = ParagraphStyle("small", parent=body, fontSize=8, textColor=colors.grey, leading=10)
    center = ParagraphStyle("center", parent=small, alignment=TA_CENTER)
    story = []

    story.append(Paragraph("Brain MRI - AI-Assisted Report", h1))
    story.append(Paragraph(f"Generated {datetime.now():%Y-%m-%d %H:%M}", center))
    story.append(Spacer(1, 6))

    # Patient table
    rows = [
        ["Patient name", patient.get("name") or "-", "Patient ID", patient.get("id") or "-"],
        ["Age", patient.get("age") or "-", "Sex", patient.get("sex") or "-"],
        ["Scan date", patient.get("scan_date") or "-", "Indication", patient.get("indication") or "-"],
    ]
    rows = [[Paragraph(_esc(c), body) for c in r] for r in rows]
    t = Table(rows, colWidths=[28*mm, 56*mm, 28*mm, 56*mm])
    t.setStyle(TableStyle([
        ("GRID", (0, 0), (-1, -1), 0.4, colors.lightgrey),
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#eef2f6")),
        ("BACKGROUND", (2, 0), (2, -1), colors.HexColor("#eef2f6")),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
    ]))
    story.append(t)

    # Result
    story.append(Paragraph("AI Classification Result", h2))
    story.append(Paragraph(
        f"<b>Predicted class:</b> {_esc(assist['predicted_class'].title())} &nbsp;&nbsp; "
        f"<b>Confidence:</b> {assist['confidence']:.1%} ({assist['confidence_level']})", body))

    prob_rows = [["Class", "Probability"]] + [
        [CLASS_NAMES[i].title(), f"{probs[i]:.1%}"] for i in range(len(probs))
    ]
    pt = Table(prob_rows, colWidths=[50*mm, 30*mm], hAlign="LEFT")
    pt.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1f3b57")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.lightgrey),
        ("FONTSIZE", (0, 0), (-1, -1), 9),
    ]))
    story.append(Spacer(1, 4))
    story.append(pt)

    # Images
    story.append(Paragraph("Images", h2))
    imgs = Table([[_pil_to_flowable(image, 75), _pil_to_flowable(cam_image, 75)],
                  [Paragraph("Uploaded scan", center), Paragraph("Grad-CAM (model attention)", center)]])
    story.append(imgs)

    # Doctor assist
    kb = assist["knowledge"]
    story.append(Paragraph("Clinical Decision Support", h2))
    story.append(Paragraph(_esc(kb["summary"]), body))
    if assist["flags"]:
        story.append(Spacer(1, 4))
        story.append(Paragraph("<b>Review flags</b>", body))
        for f in assist["flags"]:
            story.append(Paragraph("&bull; " + _esc(f), body))
    story.append(Spacer(1, 4))
    story.append(Paragraph("<b>Typical imaging features</b>", body))
    for f in kb["imaging_features"]:
        story.append(Paragraph("&bull; " + _esc(f), body))
    story.append(Spacer(1, 4))
    story.append(Paragraph("<b>Suggested next steps (for clinician consideration)</b>", body))
    for s in kb["next_steps"]:
        story.append(Paragraph("&bull; " + _esc(s), body))
    if assist["differentials"]:
        story.append(Spacer(1, 4))
        story.append(Paragraph("<b>Differentials to consider:</b> " + _esc(", ".join(assist["differentials"])), body))

    # Clinician section
    story.append(Paragraph("Clinician Notes", h2))
    story.append(Paragraph(_esc(clinician_notes).replace("\n", "<br/>") if clinician_notes
                           else "<i>No notes entered.</i>", body))
    story.append(Spacer(1, 14))
    story.append(Paragraph(f"Reviewed by: {_esc(clinician_name) or '______________________'}"
                           "&nbsp;&nbsp;&nbsp;&nbsp; Signature: ______________________", body))

    # Limitations + disclaimer
    story.append(Paragraph("Limitations", h2))
    for l in assist["limitations"]:
        story.append(Paragraph("&bull; " + _esc(l), small))
    story.append(Spacer(1, 8))
    story.append(Paragraph("<b>Disclaimer:</b> " + DISCLAIMER, small))

    doc.build(story)
    return buf.getvalue()
